-- ============================================================================
-- VITALS ENCOUNTERS (women) - PER-ROW FLAGS
-- INPUT: a table or CTE named `mahis_vitals` (output of mahis_ld_vitals.sql).
-- Generated by build_ld_round_dqa_scripts.py from the MNH Labour & Delivery data dictionary.
-- ============================================================================
WITH rounds AS (
    SELECT * FROM mahis_vitals WHERE record_type = 'woman'
),

field_status AS (
    SELECT encounter_id, person_id, 'height' AS field, CASE WHEN height IS NOT NULL THEN 1 ELSE 0 END AS present, CASE WHEN height REGEXP '^[ ]*-?[0-9]+(\\.[0-9]+)?[ ]*$' THEN 1 ELSE 0 END AS numeric_reading FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'weight_kg' AS field, CASE WHEN weight_kg IS NOT NULL THEN 1 ELSE 0 END AS present, CASE WHEN weight_kg REGEXP '^[ ]*-?[0-9]+(\\.[0-9]+)?[ ]*$' THEN 1 ELSE 0 END AS numeric_reading FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'systolic_blood_pressure' AS field, CASE WHEN systolic_blood_pressure IS NOT NULL THEN 1 ELSE 0 END AS present, CASE WHEN systolic_blood_pressure REGEXP '^[ ]*-?[0-9]+(\\.[0-9]+)?[ ]*$' THEN 1 ELSE 0 END AS numeric_reading FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'diastolic_blood_pressure' AS field, CASE WHEN diastolic_blood_pressure IS NOT NULL THEN 1 ELSE 0 END AS present, CASE WHEN diastolic_blood_pressure REGEXP '^[ ]*-?[0-9]+(\\.[0-9]+)?[ ]*$' THEN 1 ELSE 0 END AS numeric_reading FROM rounds
    UNION ALL
    SELECT encounter_id, person_id, 'pulse' AS field, CASE WHEN pulse IS NOT NULL THEN 1 ELSE 0 END AS present, CASE WHEN pulse REGEXP '^[ ]*-?[0-9]+(\\.[0-9]+)?[ ]*$' THEN 1 ELSE 0 END AS numeric_reading FROM rounds
),

round_dq AS (
    SELECT encounter_id, person_id,
        COUNT(*) AS mandatory_fields,
        SUM(present) AS mandatory_present,
        COUNT(*) - SUM(present) AS mandatory_missing,
        GROUP_CONCAT(CASE WHEN present = 0 THEN field END ORDER BY field SEPARATOR '; ') AS missing_mandatory_fields
    FROM field_status
    GROUP BY encounter_id, person_id
)

SELECT
    m.person_id, m.location_id, m.encounter_id, m.visit_date, m.vitals_time,
    d.mandatory_fields, d.mandatory_present, d.mandatory_missing,
    ROUND(100 * d.mandatory_present / d.mandatory_fields, 1) AS pct_mandatory_present,
    CASE WHEN d.mandatory_missing = 0 THEN 'YES' ELSE 'NO' END AS all_mandatory_present,
    d.missing_mandatory_fields
FROM rounds m
INNER JOIN round_dq d ON d.encounter_id = m.encounter_id AND d.person_id = m.person_id
ORDER BY d.mandatory_missing DESC, m.person_id, m.visit_date;
